 $('browserLaunch').onclick=()=>browser({action:{action:'launch',executable:null,headless:false}});$('browserClose').onclick=()=>browser({action:{action:'close'}});$('browserSnapshot').onclick=()=>browser({action:{action:'snapshot'}});$('browserNavigate').onclick=()=>browser({action:{action:'navigate',url:$('browserUrl').value}});
 $('browserDo').onclick=()=>{const a=$('browserAction').value,t=$('browserTarget').value,text=$('browserText').value;if(a==='click')return browser({action:{action:'click',target:{kind:'css',value:t}}},true);if(a==='type')return browser({action:{action:'type',target:{kind:'css',value:t},text}},true);if(a==='press_key')return browser({action:{action:'press_key',key:t}},true);return browser({action:{action:'evaluate',expression:t}},true)};
-$('computerDo').onclick=async()=>{try{const app=$('computerApp').value,a=$('computerAction').value,v=$('computerValue').value;let action;if(a==='screenshot')action={action:'screenshot',app};if(a==='type')action={action:'type',app,text:v};if(a==='key_press')action={action:'key_press',app,key:v};if(a==='click'){const [x,y]=v.split(',').map(Number);if(!Number.isFinite(x)||!Number.isFinite(y))throw new Error('坐标格式应为 x,y');action={action:'click',app,x,y}}const write=a!=='screenshot';if(write&&!approved('允许 Zero3 Pilot 操作 '+app+'？'))return;await submit('/api/v1/jobs/computer',{action,granted_level:'Standard',approved:write},$('computerOut'))}catch(e){$('computerOut').textContent=e.message;log(e.message)}};
+$('computerDo').onclick=async()=>{try{const app=$('computerApp').value,a=$('computerAction').value,v=$('computerValue').value;let action;if(a==='list_apps')action={action:'list_apps'};if(a==='screenshot')action={action:'screenshot',app};if(a==='type')action={action:'type',app,text:v};if(a==='key_press')action={action:'key_press',app,key:v};if(a==='click'){const [x,y]=v.split(',').map(Number);if(!Number.isFinite(x)||!Number.isFinite(y))throw new Error('坐标格式应为 x,y');action={action:'click',app,x,y}}const write=!['list_apps','screenshot'].includes(a);if(write&&!approved('允许 Zero3 Pilot 操作 '+app+'？'))return;await submit('/api/v1/jobs/computer',{action,granted_level:'Standard',approved:write},$('computerOut'))}catch(e){$('computerOut').textContent=e.message;log(e.message)}};
 $('createSchedule').onclick=async()=>{try{if(!approved('创建持久化自动化？到期后将自动执行 Agent。'))return;const kind=$('scheduleKind').value,val=$('scheduleValue').value;let schedule,first;if(kind==='every'){schedule={kind:'every_seconds',seconds:Number(val)};first=new Date().toISOString()}else if(kind==='once'){schedule={kind:'once'};first=new Date(val).toISOString()}else{const [hour,minute]=val.split(':').map(Number);schedule={kind:'daily_utc',hour,minute};const d=new Date();d.setUTCDate(d.getUTCDate()+1);d.setUTCHours(hour,minute,0,0);first=d.toISOString()}const payload={backend:$('scheduleBackend').value,goal:$('scheduleGoal').value,context:{},granted_level:'Standard',approved:true};const r=await api('/api/v1/schedules',{method:'POST',body:JSON.stringify({job_kind:'subagent',payload,schedule,first_run_at:first,granted_level:'Standard',approved:true})});log(r);refreshSchedules();refreshStatus()}catch(e){log(e.message)}};
 $('saveMemory').onclick=async()=>{try{const personal=$('memoryClass').value==='personal';const ok=!personal||approved('这是个人长期记忆。确认允许 Zero3 Pilot 持久保存？');if(!ok)return;await api('/api/v1/memory',{method:'POST',body:JSON.stringify({key:$('memoryKey').value,value:parseJson($('memoryValue').value,null),class:$('memoryClass').value,scope:{kind:'global'},source:'desktop-ui',approved:personal})});refreshMemory();refreshStatus();log('记忆已保存')}catch(e){log(e.message)}};
